INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (1, 1, '', 'หน้าหลัก', 'เว็บไซต์{SITE_NAME} ข่าวประชาสัมพันธ์ ประกาศ กิจกรรม และข้อมูลสำหรับนักเรียนและผู้ปกครอง', '<h2>ยินดีต้อนรับสู่{SITE_NAME}</h2><p>{SITE_NAME} มุ่งพัฒนาผู้เรียนให้เป็น<strong>คนดี คนเก่ง และมีความสุข</strong> มีทักษะการเรียนรู้ในศตวรรษที่ 21 ภายใต้ความร่วมมือของครู ผู้ปกครอง และชุมชน</p><ul><li><a href="{WEBURL}announce">ประกาศโรงเรียน</a> — รับสมัครนักเรียน ประกาศผล และจัดซื้อจัดจ้าง</li><li><a href="{WEBURL}news">ข่าวประชาสัมพันธ์</a> — กิจกรรมและผลงานของนักเรียนและครู</li><li><a href="{WEBURL}edocument">หนังสือราชการ</a> — เอกสารเวียนสำหรับครูและบุคลากร</li><li><a href="{WEBURL}download">ดาวน์โหลด</a> — แบบฟอร์มสำหรับนักเรียนและผู้ปกครอง</li></ul><p><em>เนื้อหาทั้งหมดเป็นข้อมูลตัวอย่าง แก้ไขได้ที่หน้าผู้ดูแล › หน้าเพจ</em></p>', 'โรงเรียน,ข่าวประชาสัมพันธ์,กิจกรรม,{SITE_NAME}');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (2, 2, '', 'ข่าวประชาสัมพันธ์', 'ข่าวกิจกรรม ผลงานนักเรียนและครูของ{SITE_NAME}', '<p>ข่าวสารและกิจกรรมของโรงเรียน อัปเดตทุกสัปดาห์</p>', 'ข่าวประชาสัมพันธ์,กิจกรรม,ผลงานนักเรียน');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (3, 3, '', 'ประกาศโรงเรียน', 'ประกาศรับสมัครนักเรียน ประกาศผล และประกาศจัดซื้อจัดจ้างของ{SITE_NAME}', '<p>ประกาศอย่างเป็นทางการของโรงเรียน</p>', 'ประกาศ,รับสมัครนักเรียน,จัดซื้อจัดจ้าง');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (4, 4, '', 'สาระน่ารู้', 'บทความความรู้ ผลงานครู และแนะแนวการศึกษาต่อจาก{SITE_NAME}', '<p>บทความและสาระความรู้สำหรับนักเรียน ผู้ปกครอง และครู</p>', 'สาระน่ารู้,บทความ,ผลงานครู,แนะแนว');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (5, 5, '', 'บุคลากร', 'ทำเนียบผู้บริหาร ครู และบุคลากรของ{SITE_NAME}', '<p>ผู้บริหาร ครู และบุคลากรทางการศึกษา (รายชื่อเป็นข้อมูลตัวอย่าง)</p>', 'บุคลากร,ผู้บริหาร,ครู');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (6, 6, '', 'ภาพกิจกรรม', 'ประมวลภาพกิจกรรมของนักเรียนและครู{SITE_NAME}', '', 'ภาพกิจกรรม,อัลบั้ม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (7, 7, '', 'ดาวน์โหลดเอกสาร', 'แบบฟอร์มสำหรับนักเรียนและผู้ปกครอง ปฏิทินการศึกษา และเอกสารเผยแพร่ของ{SITE_NAME}', '', 'ดาวน์โหลด,แบบฟอร์ม,ใบสมัคร,ปฏิทินการศึกษา');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (8, 8, '', 'ปฏิทินกิจกรรม', 'กำหนดการกิจกรรมสำคัญตลอดภาคเรียนของ{SITE_NAME}', '', 'ปฏิทิน,กิจกรรม,กำหนดการ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (9, 9, '', 'วิดีโอ', 'วิดีโอแนะนำโรงเรียนและกิจกรรมของนักเรียน', '', 'วิดีโอ,YouTube,กิจกรรม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (10, 10, '', 'กระดานถาม-ตอบ', 'ถาม-ตอบสำหรับนักเรียนและผู้ปกครอง{SITE_NAME}', '', 'ถาม-ตอบ,เว็บบอร์ด,ผู้ปกครอง');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (11, 11, '', 'หนังสือราชการ', 'หนังสือราชการและเอกสารเวียนของ{SITE_NAME}', '', 'หนังสือราชการ,e-Document,เอกสารเวียน');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (12, 12, '', 'ประวัติโรงเรียน', 'ประวัติความเป็นมาและข้อมูลพื้นฐานของ{SITE_NAME}', '<h2>ประวัติความเป็นมา</h2><p>{SITE_NAME} ก่อตั้งขึ้นด้วยความร่วมมือของชุมชน เพื่อจัดการศึกษาให้แก่เยาวชนในท้องถิ่น จากอาคารเรียนไม้หลังแรกเพียงหลังเดียว ปัจจุบันโรงเรียนมีอาคารเรียน ห้องปฏิบัติการ ห้องสมุด และแหล่งเรียนรู้ที่ทันสมัย</p><h2>ข้อมูลพื้นฐาน</h2><table><tbody><tr><th>ชื่อสถานศึกษา</th><td>{SITE_NAME}</td></tr><tr><th>ระดับที่เปิดสอน</th><td>มัธยมศึกษาปีที่ 1 – 6</td></tr><tr><th>จำนวนนักเรียน</th><td>1,250 คน</td></tr><tr><th>จำนวนครูและบุคลากร</th><td>72 คน</td></tr><tr><th>สีประจำโรงเรียน</th><td>ส้ม – ฟ้า</td></tr><tr><th>คำขวัญ</th><td>เรียนดี มีวินัย ใฝ่คุณธรรม นำสังคม</td></tr></tbody></table><p>ดูรายชื่อผู้บริหารและครูได้ที่ <a href="{WEBURL}personnel">บุคลากร</a></p>', 'ประวัติโรงเรียน,ข้อมูลพื้นฐาน');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (13, 13, '', 'วิสัยทัศน์ พันธกิจ', 'วิสัยทัศน์ พันธกิจ เป้าประสงค์ และอัตลักษณ์ของ{SITE_NAME}', '<h2>วิสัยทัศน์</h2><blockquote>{SITE_NAME} เป็นองค์กรแห่งการเรียนรู้ ผู้เรียนมีคุณภาพตามมาตรฐาน มีคุณธรรม ก้าวทันเทคโนโลยี และดำเนินชีวิตตามหลักปรัชญาของเศรษฐกิจพอเพียง</blockquote><h2>พันธกิจ</h2><ol><li>จัดการศึกษาให้ผู้เรียนมีคุณภาพตามมาตรฐานการศึกษาชาติ</li><li>ปลูกฝังคุณธรรม จริยธรรม และค่านิยมที่พึงประสงค์</li><li>พัฒนาครูและบุคลากรให้มีความเชี่ยวชาญทางวิชาชีพ</li><li>พัฒนาแหล่งเรียนรู้และเทคโนโลยีเพื่อการเรียนรู้</li><li>ส่งเสริมการมีส่วนร่วมของผู้ปกครองและชุมชน</li></ol><h2>เป้าประสงค์</h2><ul><li>ผู้เรียนมีผลสัมฤทธิ์ทางการเรียนสูงขึ้น</li><li>ผู้เรียนมีทักษะชีวิตและทักษะอาชีพ</li><li>โรงเรียนเป็นที่ยอมรับของชุมชน</li></ul><h2>อัตลักษณ์และเอกลักษณ์</h2><p><strong>อัตลักษณ์ :</strong> ยิ้ม ไหว้ ทักทาย มีน้ำใจ<br><strong>เอกลักษณ์ :</strong> โรงเรียนสะอาด ร่มรื่น เป็นแหล่งเรียนรู้ของชุมชน</p>', 'วิสัยทัศน์,พันธกิจ,เป้าประสงค์,อัตลักษณ์');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (14, 14, '', 'โครงสร้างการบริหาร', 'โครงสร้างการบริหารงานสี่กลุ่มงานของ{SITE_NAME}', '<h2>โครงสร้างการบริหารสถานศึกษา</h2><p>การบริหารงานของโรงเรียนแบ่งเป็น 4 กลุ่มงาน ภายใต้การกำกับของผู้อำนวยการและคณะกรรมการสถานศึกษาขั้นพื้นฐาน</p><ul><li><strong>ผู้อำนวยการโรงเรียน</strong><ul><li><strong>คณะกรรมการสถานศึกษาขั้นพื้นฐาน</strong> — ให้ความเห็นชอบนโยบายและแผน</li><li><strong>กลุ่มบริหารวิชาการ</strong> — หลักสูตร การจัดการเรียนรู้ วัดผลประเมินผล ทะเบียน แนะแนว</li><li><strong>กลุ่มบริหารงานบุคคล</strong> — อัตรากำลัง พัฒนาบุคลากร วินัยและการประเมิน</li><li><strong>กลุ่มบริหารงบประมาณ</strong> — แผนงาน การเงิน บัญชี พัสดุ</li><li><strong>กลุ่มบริหารทั่วไป</strong> — ธุรการ อาคารสถานที่ กิจการนักเรียน ชุมชนสัมพันธ์</li></ul></li></ul><table><thead><tr><th>กลุ่มงาน</th><th>ผู้รับผิดชอบ</th></tr></thead><tbody><tr><td>กลุ่มบริหารวิชาการ</td><td>รองผู้อำนวยการกลุ่มบริหารวิชาการ</td></tr><tr><td>กลุ่มบริหารงานบุคคลและงบประมาณ</td><td>รองผู้อำนวยการกลุ่มบริหารงานบุคคลและงบประมาณ</td></tr><tr><td>กลุ่มบริหารทั่วไป</td><td>รองผู้อำนวยการกลุ่มบริหารทั่วไป</td></tr></tbody></table><p>ดูรายชื่อบุคลากรแต่ละกลุ่มได้ที่ <a href="{WEBURL}personnel">บุคลากร</a></p>', 'โครงสร้างการบริหาร,กลุ่มงาน');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (15, 15, '', 'ติดต่อโรงเรียน', 'ที่อยู่ เบอร์โทรศัพท์ และช่องทางติดต่อ{SITE_NAME}', '<h2>ติดต่อ{SITE_NAME}</h2><p><strong>ที่อยู่ :</strong> เลขที่ 99 หมู่ 9 ตำบลตัวอย่าง อำเภอตัวอย่าง จังหวัดตัวอย่าง 99999<br><strong>โทรศัพท์ :</strong> 0-0000-0000<br><strong>อีเมล :</strong> {SITE_EMAIL}<br><strong>เวลาทำการ :</strong> จันทร์ – ศุกร์ 08.00 – 16.30 น.</p><h3>หน่วยงานภายใน</h3><table><tbody><tr><th>ห้องธุรการ</th><td>ต่อ 101</td></tr><tr><th>งานรับสมัครนักเรียน</th><td>ต่อ 102</td></tr><tr><th>งานกิจการนักเรียน</th><td>ต่อ 103</td></tr></tbody></table><p>สอบถามเรื่องทั่วไปได้ที่ <a href="{WEBURL}forum">กระดานถาม-ตอบ</a></p><p><em>ข้อมูลติดต่อเป็นตัวอย่าง แก้ไขได้ที่หน้าผู้ดูแล › หน้าเพจ › ติดต่อโรงเรียน</em></p>', 'ติดต่อ,ที่อยู่,โทรศัพท์');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (16, 2, '', 'นักเรียนคว้ารางวัลเหรียญทองการแข่งขันทักษะวิชาการระดับเขตพื้นที่', 'ตัวแทนนักเรียนได้รับรางวัลเหรียญทอง 5 รายการ และเป็นตัวแทนเขตพื้นที่ไปแข่งขันระดับภาค', '<p>ขอแสดงความยินดีกับตัวแทนนักเรียนของ{SITE_NAME} ที่ได้รับ<strong>รางวัลเหรียญทอง 5 รายการ</strong> ในการแข่งขันทักษะวิชาการระดับเขตพื้นที่การศึกษา และได้รับคัดเลือกเป็นตัวแทนไปแข่งขันในระดับภาค</p><table><thead><tr><th>รายการ</th><th>ผลการแข่งขัน</th></tr></thead><tbody><tr><td>โครงงานวิทยาศาสตร์ ม.ต้น</td><td>เหรียญทอง ชนะเลิศ</td></tr><tr><td>อ่านเอาเรื่องภาษาไทย</td><td>เหรียญทอง</td></tr><tr><td>แข่งขันหุ่นยนต์</td><td>เหรียญทอง รองชนะเลิศอันดับ 1</td></tr><tr><td>ประกวดสุนทรพจน์ภาษาอังกฤษ</td><td>เหรียญทอง</td></tr><tr><td>การประกวดวาดภาพ</td><td>เหรียญทอง</td></tr></tbody></table>', 'รางวัล,ผลงานนักเรียน,ทักษะวิชาการ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (17, 2, '', 'กิจกรรมวันไหว้ครูประจำปีการศึกษา', 'นักเรียนทุกระดับชั้นร่วมพิธีไหว้ครูเพื่อแสดงความกตัญญูกตเวทีต่อครูผู้ประสิทธิ์ประสาทวิชา', '<p>โรงเรียนจัดพิธีไหว้ครูประจำปีการศึกษา ณ หอประชุมโรงเรียน โดยมีผู้อำนวยการเป็นประธานในพิธี นักเรียนแต่ละห้องร่วมกันจัดทำพานดอกไม้อย่างสวยงาม และมีการมอบเกียรติบัตรแก่นักเรียนที่มีผลการเรียนดีเด่น</p><p>ชมภาพบรรยากาศได้ที่ <a href="{WEBURL}gallery">ภาพกิจกรรม</a></p>', 'วันไหว้ครู,กิจกรรม,คุณธรรม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (18, 2, '', 'ประชุมผู้ปกครองนักเรียนภาคเรียนนี้', 'ขอเชิญผู้ปกครองนักเรียนทุกระดับชั้นร่วมประชุมเพื่อรับทราบแนวทางการจัดการเรียนการสอน', '<p>โรงเรียนขอเชิญผู้ปกครองนักเรียนทุกระดับชั้นเข้าร่วมประชุมผู้ปกครองประจำภาคเรียน ลงทะเบียนเวลา 08.30 น. ณ หอประชุม จากนั้นพบครูที่ปรึกษาที่ห้องเรียนของนักเรียน</p><h3>วาระการประชุม</h3><ol><li>นโยบายและผลการดำเนินงานของโรงเรียน</li><li>การดูแลช่วยเหลือนักเรียน</li><li>ปฏิทินกิจกรรมภาคเรียน</li><li>ผู้ปกครองพบครูที่ปรึกษา</li></ol><p>ดาวน์โหลดหนังสือเชิญได้ที่ <a href="{WEBURL}edocument">หนังสือราชการ</a></p>', 'ผู้ปกครอง,ประชุม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (19, 2, '', 'ค่ายวิทยาศาสตร์ สนุกคิด ทดลองจริง', 'นักเรียนชั้น ม.1-ม.3 ร่วมทำการทดลองและสร้างสิ่งประดิษฐ์ในค่ายวิทยาศาสตร์สองวัน', '<p>กลุ่มสาระการเรียนรู้วิทยาศาสตร์และเทคโนโลยีจัดค่ายวิทยาศาสตร์สำหรับนักเรียนชั้น ม.1-ม.3 นักเรียนได้ทดลองสร้างจรวดขวดน้ำ ประกอบวงจรไฟฟ้าอย่างง่าย และเขียนโปรแกรมควบคุมหุ่นยนต์</p>', 'ค่ายวิทยาศาสตร์,STEM,กิจกรรม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (20, 2, '', 'การแข่งขันกีฬาสีภายในประจำปี', 'นักเรียนสี่คณะสีร่วมแข่งขันกีฬาและขบวนพาเหรดอย่างสนุกสนาน ส่งเสริมความสามัคคีและน้ำใจนักกีฬา', '<p>การแข่งขันกีฬาสีภายในประจำปีจัดขึ้นเป็นเวลาสองวัน มีการแข่งขันฟุตบอล วอลเลย์บอล กรีฑา และกีฬาพื้นบ้าน พร้อมขบวนพาเหรดและกองเชียร์ของแต่ละคณะสี</p><p>ขอบคุณผู้ปกครองและชุมชนที่ร่วมให้กำลังใจนักเรียนตลอดการแข่งขัน</p>', 'กีฬาสี,กิจกรรม,สุขภาพ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (21, 2, '', 'โรงเรียนผ่านการประเมินสถานศึกษาปลอดภัยระดับดีเยี่ยม', 'ผลการประเมินสถานศึกษาปลอดภัยอยู่ในระดับดีเยี่ยม ด้านอาคารสถานที่ การจราจร และการเฝ้าระวังภัย', '<p>{SITE_NAME} ผ่านการประเมินสถานศึกษาปลอดภัยในระดับ<strong>ดีเยี่ยม</strong> ครอบคลุมด้านอาคารสถานที่ ความปลอดภัยทางถนนหน้าโรงเรียน และระบบเฝ้าระวังภัยสำหรับนักเรียน</p>', 'ประกันคุณภาพ,ความปลอดภัย');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (22, 2, '', 'ครูได้รับรางวัลครูดีเด่นด้านนวัตกรรมการสอน', 'ผลงานสื่อการสอนคณิตศาสตร์แบบเกมได้รับรางวัลครูดีเด่นด้านนวัตกรรมการสอนระดับจังหวัด', '<p>ขอแสดงความยินดีกับครูกลุ่มสาระคณิตศาสตร์ ที่ได้รับรางวัลครูดีเด่นด้านนวัตกรรมการสอนระดับจังหวัด จากผลงาน "คณิตศาสตร์สนุกด้วยเกมกระดาน" ที่ช่วยให้นักเรียนเข้าใจเรื่องเศษส่วนได้ดีขึ้น</p><p>อ่านบทความของครูเจ้าของผลงานได้ที่ <a href="{WEBURL}knowledge">สาระน่ารู้</a></p>', 'ผลงานครู,รางวัล,นวัตกรรม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (23, 2, '', 'โครงการอาหารกลางวันปลอดภัย ผักจากแปลงเกษตรในโรงเรียน', 'นักเรียนปลูกผักปลอดสารในแปลงเกษตรของโรงเรียน นำมาประกอบอาหารกลางวันให้เพื่อน ๆ', '<p>นักเรียนชุมนุมเกษตรร่วมกันปลูกผักปลอดสารพิษในแปลงเกษตรของโรงเรียน ผลผลิตส่งให้โรงอาหารประกอบอาหารกลางวัน ช่วยให้นักเรียนได้รับประทานอาหารที่สะอาด ปลอดภัย และเรียนรู้การทำเกษตรตามหลักปรัชญาของเศรษฐกิจพอเพียง</p>', 'อาหารกลางวัน,เกษตรในโรงเรียน');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (24, 2, '', 'อบรมปฐมพยาบาลเบื้องต้นสำหรับนักเรียนแกนนำ', 'นักเรียนแกนนำอนามัยโรงเรียนเรียนรู้การปฐมพยาบาลและการช่วยฟื้นคืนชีพเบื้องต้น', '<p>งานอนามัยโรงเรียนร่วมกับหน่วยบริการสุขภาพในชุมชนจัดอบรมการปฐมพยาบาลเบื้องต้นให้นักเรียนแกนนำ ฝึกปฏิบัติการช่วยฟื้นคืนชีพ การห้ามเลือด และการเคลื่อนย้ายผู้บาดเจ็บ</p>', 'สุขภาพ,อบรม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (25, 2, '', 'นักเรียนร่วมกิจกรรมจิตอาสาพัฒนาชุมชน', 'นักเรียนและครูร่วมทำความสะอาดวัดและทาสีศาลาพักริมทางในชุมชน', '<p>นักเรียนสภานักเรียนและครูร่วมกิจกรรมจิตอาสา ทำความสะอาดวัดประจำชุมชนและทาสีศาลาพักริมทาง ปลูกฝังความรับผิดชอบต่อสังคมและความภาคภูมิใจในท้องถิ่น</p>', 'จิตอาสา,ชุมชน,คุณธรรม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (26, 2, '', 'ทีมหุ่นยนต์ของโรงเรียนผ่านเข้ารอบระดับประเทศ', 'ทีมหุ่นยนต์ของโรงเรียนผ่านการคัดเลือกระดับภาค เตรียมแข่งขันรอบชิงชนะเลิศระดับประเทศ', '<p>ทีมหุ่นยนต์ของ{SITE_NAME} ผ่านการคัดเลือกระดับภาค และได้สิทธิ์เข้าแข่งขันรอบชิงชนะเลิศระดับประเทศ นักเรียนออกแบบหุ่นยนต์คัดแยกขยะอัตโนมัติ เขียนโปรแกรมและประกอบเองทั้งหมด</p>', 'หุ่นยนต์,ผลงานนักเรียน,STEM');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (27, 2, '', 'ขอเชิญร่วมงานวันวิทยาศาสตร์และนิทรรศการวิชาการ', 'ชมนิทรรศการผลงานนักเรียน การแสดงทางวิทยาศาสตร์ และการประกวดโครงงาน เปิดให้ชุมชนเข้าชมฟรี', '<p>โรงเรียนขอเชิญผู้ปกครองและชุมชนร่วมงานวันวิทยาศาสตร์และนิทรรศการวิชาการ ภายในงานมีการแสดงทางวิทยาศาสตร์ การประกวดโครงงาน และฐานกิจกรรมสำหรับเด็กเล็ก ดูวันเวลาได้ที่ <a href="{WEBURL}event">ปฏิทินกิจกรรม</a></p>', 'วันวิทยาศาสตร์,นิทรรศการ,STEM');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (28, 2, '', 'ต้อนรับคณะศึกษาดูงานจากโรงเรียนเครือข่าย', 'ผู้บริหารและครูจากโรงเรียนเครือข่ายศึกษาดูงานการจัดการเรียนรู้เชิงรุกและระบบดูแลช่วยเหลือนักเรียน', '<p>{SITE_NAME} ให้การต้อนรับคณะผู้บริหารและครูจากโรงเรียนเครือข่าย ที่มาศึกษาดูงานการจัดการเรียนรู้เชิงรุก (Active Learning) และระบบดูแลช่วยเหลือนักเรียน พร้อมแลกเปลี่ยนประสบการณ์ระหว่างกัน</p>', 'ศึกษาดูงาน,เครือข่าย');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (29, 3, '', 'ประกาศรับสมัครนักเรียนชั้น ม.1 และ ม.4 ปีการศึกษาหน้า', 'รับสมัครนักเรียนชั้น ม.1 และ ม.4 ประเภทห้องเรียนทั่วไปและห้องเรียนพิเศษ สมัครได้ทั้งที่โรงเรียนและออนไลน์', '<p>{SITE_NAME} เปิดรับสมัครนักเรียนชั้นมัธยมศึกษาปีที่ 1 และ 4 ประจำปีการศึกษาหน้า</p><table><thead><tr><th>ระดับชั้น</th><th>ประเภท</th><th>จำนวนรับ</th></tr></thead><tbody><tr><td>ม.1</td><td>ห้องเรียนทั่วไป</td><td>160 คน</td></tr><tr><td>ม.1</td><td>ห้องเรียนพิเศษวิทยาศาสตร์-คณิตศาสตร์</td><td>36 คน</td></tr><tr><td>ม.4</td><td>ห้องเรียนทั่วไป</td><td>120 คน</td></tr></tbody></table><h3>หลักฐานการสมัคร</h3><ol><li>ใบสมัคร (ดาวน์โหลดได้ที่ <a href="{WEBURL}download">ดาวน์โหลด</a>)</li><li>สำเนาทะเบียนบ้านนักเรียนและผู้ปกครอง</li><li>หลักฐานการศึกษา</li><li>รูปถ่าย 1.5 นิ้ว 2 รูป</li></ol>', 'รับสมัครนักเรียน,ประกาศ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (30, 3, '', 'ประกาศผลการคัดเลือกนักเรียนรับทุนการศึกษา', 'รายชื่อนักเรียนที่ได้รับทุนการศึกษาประจำปี และกำหนดการรับทุน', '<p>ประกาศรายชื่อนักเรียนที่ผ่านการคัดเลือกรับทุนการศึกษาประจำปี จำนวน 25 ทุน นักเรียนที่มีรายชื่อพร้อมผู้ปกครองติดต่อรับทุนที่ห้องกิจการนักเรียนตามวันที่กำหนดใน <a href="{WEBURL}event">ปฏิทินกิจกรรม</a></p>', 'ทุนการศึกษา,ประกาศ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (31, 3, '', 'ประกาศประกวดราคาจ้างปรับปรุงห้องปฏิบัติการคอมพิวเตอร์', 'ประกวดราคาจ้างปรับปรุงห้องปฏิบัติการคอมพิวเตอร์ 1 ห้อง ด้วยวิธีประกวดราคาอิเล็กทรอนิกส์', '<p>{SITE_NAME} มีความประสงค์จะประกวดราคาจ้างปรับปรุงห้องปฏิบัติการคอมพิวเตอร์ จำนวน 1 ห้อง ด้วยวิธีประกวดราคาอิเล็กทรอนิกส์ ผู้สนใจดูรายละเอียดและดาวน์โหลดเอกสารประกวดราคาได้ที่ระบบจัดซื้อจัดจ้างภาครัฐ</p><p><em>ประกาศนี้เป็นข้อมูลตัวอย่าง</em></p>', 'จัดซื้อจัดจ้าง');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (32, 3, '', 'ประกาศรายชื่อผู้มีสิทธิ์สอบคัดเลือกนักเรียนห้องเรียนพิเศษ', 'ตรวจสอบรายชื่อ เลขที่นั่งสอบ และห้องสอบ พร้อมข้อปฏิบัติในวันสอบ', '<p>ประกาศรายชื่อผู้มีสิทธิ์สอบคัดเลือกเข้าเรียนห้องเรียนพิเศษวิทยาศาสตร์-คณิตศาสตร์ ชั้น ม.1</p><h3>ข้อปฏิบัติในวันสอบ</h3><ul><li>มาถึงสนามสอบก่อนเวลา 30 นาที</li><li>นำบัตรประจำตัวผู้สมัครสอบและบัตรประชาชนมาด้วย</li><li>ห้ามนำอุปกรณ์สื่อสารเข้าห้องสอบ</li></ul>', 'รับสมัครนักเรียน,สอบคัดเลือก');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (33, 3, '', 'ประกาศวันหยุดเรียนกรณีพิเศษ', 'โรงเรียนหยุดเรียนกรณีพิเศษเนื่องจากใช้สถานที่เป็นสนามสอบ และจะสอนชดเชยในวันเสาร์ถัดไป', '<p>เนื่องจากโรงเรียนได้รับเลือกเป็นสนามสอบระดับชาติ จึงประกาศหยุดเรียนกรณีพิเศษ 1 วัน และจัดการเรียนการสอนชดเชยในวันเสาร์ถัดไป ขอให้นักเรียนติดตามรายละเอียดจากครูที่ปรึกษา</p>', 'ประกาศ,วันหยุด');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (34, 3, '', 'ประกาศผู้ชนะการเสนอราคาซื้อวัสดุการศึกษา', 'ประกาศผู้ชนะการเสนอราคาซื้อวัสดุการศึกษาประจำภาคเรียน โดยวิธีเฉพาะเจาะจง', '<p>ตามที่โรงเรียนได้ดำเนินการซื้อวัสดุการศึกษาประจำภาคเรียน โดยวิธีเฉพาะเจาะจง บัดนี้ได้ผู้ชนะการเสนอราคาแล้ว รายละเอียดตามประกาศแนบท้าย</p><p><em>ประกาศนี้เป็นข้อมูลตัวอย่าง</em></p>', 'จัดซื้อจัดจ้าง');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (35, 3, '', 'กำหนดการมอบตัวนักเรียนใหม่', 'กำหนดการมอบตัวและเอกสารที่ต้องใช้สำหรับนักเรียนที่ผ่านการคัดเลือก', '<p>นักเรียนที่ผ่านการคัดเลือกพร้อมผู้ปกครองมามอบตัวตามวันและเวลาที่กำหนด ณ หอประชุมโรงเรียน</p><ol><li>ใบมอบตัว (รับได้ที่โรงเรียน)</li><li>สำเนาทะเบียนบ้านและบัตรประชาชน</li><li>ใบแสดงผลการเรียน</li></ol>', 'รับสมัครนักเรียน,มอบตัว');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (36, 3, '', 'ประกาศเจตนารมณ์ต่อต้านการทุจริตของโรงเรียน', 'ผู้บริหาร ครู และบุคลากรร่วมประกาศเจตนารมณ์ปฏิบัติหน้าที่ด้วยความซื่อสัตย์สุจริต โปร่งใส ตรวจสอบได้', '<p>ผู้บริหาร ครู และบุคลากรของ{SITE_NAME} ร่วมประกาศเจตนารมณ์ต่อต้านการทุจริต ปฏิบัติหน้าที่ด้วยความซื่อสัตย์สุจริต โปร่งใส ตรวจสอบได้ ตามแนวทางการประเมินคุณธรรมและความโปร่งใส (ITA)</p>', 'ITA,คุณธรรม,ประกาศ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (37, 4, '', '5 เทคนิคช่วยลูกอ่านหนังสือให้สนุกที่บ้าน', 'แนวทางง่าย ๆ ที่ผู้ปกครองนำไปใช้ได้ทันที เพื่อสร้างนิสัยรักการอ่านให้ลูก', '<ol><li><strong>อ่านด้วยกันทุกวัน</strong> แม้เพียงวันละ 10 นาที</li><li><strong>ให้ลูกเลือกหนังสือเอง</strong></li><li><strong>จัดมุมอ่านหนังสือ</strong> ที่สบายและแสงสว่างเพียงพอ</li><li><strong>เป็นแบบอย่าง</strong> ให้ลูกเห็นผู้ใหญ่อ่านหนังสือ</li><li><strong>ชวนคุยหลังอ่าน</strong> เพื่อฝึกการคิดวิเคราะห์</li></ol>', 'การอ่าน,ผู้ปกครอง');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (38, 4, '', 'ทำความรู้จักการเรียนรู้เชิงรุก Active Learning', 'ห้องเรียนที่นักเรียนได้ลงมือทำ คิด และแก้ปัญหาด้วยตนเอง', '<p>การเรียนรู้เชิงรุกเปลี่ยนบทบาทนักเรียนจากผู้ฟังเป็นผู้ลงมือทำ ครูเป็นผู้อำนวยความสะดวก</p><ul><li>เรียนรู้ผ่านโครงงานและปัญหาจริง</li><li>ทำงานเป็นทีมและนำเสนอ</li><li>สะท้อนคิดหลังเรียนทุกครั้ง</li></ul>', 'Active Learning,นวัตกรรม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (39, 4, '', 'คณิตศาสตร์สนุกด้วยเกมกระดาน', 'นวัตกรรมสื่อการสอนเรื่องเศษส่วนที่ได้รับรางวัลครูดีเด่นระดับจังหวัด', '<p>เกมกระดาน "ตลาดเศษส่วน" ให้นักเรียนซื้อขายสินค้าด้วยการคิดเศษส่วน ผลการใช้พบว่าคะแนนเฉลี่ยเรื่องเศษส่วนของนักเรียนเพิ่มขึ้นร้อยละ 18</p><p>ครูที่สนใจดาวน์โหลดสื่อได้ที่ <a href="{WEBURL}download">ดาวน์โหลด</a></p>', 'ผลงานครู,คณิตศาสตร์,นวัตกรรม');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (40, 4, '', 'เตรียมตัวสอบเข้ามหาวิทยาลัยอย่างไรให้พร้อม', 'วางแผนการเตรียมตัวตั้งแต่ ม.4 เลือกคณะ ทำแฟ้มสะสมผลงาน และจัดการเวลาอ่านหนังสือ', '<ol><li>สำรวจความถนัดและความสนใจของตนเอง</li><li>ศึกษาเกณฑ์การรับสมัครของคณะที่สนใจ</li><li>สะสมผลงานและกิจกรรมอย่างต่อเนื่อง</li><li>วางตารางอ่านหนังสือและทำข้อสอบเก่า</li></ol>', 'แนะแนว,ศึกษาต่อ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (41, 4, '', 'รู้ทันภัยออนไลน์ ใช้สื่อสังคมอย่างปลอดภัย', 'ข้อควรระวังในการใช้สื่อสังคมออนไลน์สำหรับนักเรียน และวิธีรับมือกับการกลั่นแกล้งออนไลน์', '<ul><li>ไม่เปิดเผยข้อมูลส่วนตัวและตำแหน่งที่อยู่</li><li>ตั้งรหัสผ่านที่คาดเดายาก</li><li>คิดก่อนโพสต์และคิดก่อนแชร์</li><li>ถูกกลั่นแกล้งออนไลน์ให้บอกครูหรือผู้ปกครองทันที</li></ul>', 'ความปลอดภัย,ดิจิทัล');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (42, 4, '', 'อาชีพแห่งอนาคตที่นักเรียนควรรู้จัก', 'อาชีพที่ตลาดต้องการสูงในอนาคต และทักษะที่ควรเริ่มฝึกตั้งแต่วันนี้', '<table><thead><tr><th>อาชีพ</th><th>ทักษะที่ควรฝึก</th></tr></thead><tbody><tr><td>นักวิเคราะห์ข้อมูล</td><td>คณิตศาสตร์ สถิติ การเขียนโปรแกรม</td></tr><tr><td>นักพัฒนาซอฟต์แวร์</td><td>การคิดเชิงคำนวณ ภาษาอังกฤษ</td></tr><tr><td>ผู้เชี่ยวชาญด้านสิ่งแวดล้อม</td><td>วิทยาศาสตร์ การสื่อสาร</td></tr><tr><td>นักสร้างสรรค์คอนเทนต์</td><td>การเล่าเรื่อง การออกแบบ</td></tr></tbody></table>', 'แนะแนว,อาชีพ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (43, 4, '', 'ปลูกผักสวนครัวในกระถาง ทำได้ง่ายที่บ้าน', 'ขั้นตอนปลูกผักสวนครัวในกระถางสำหรับบ้านที่มีพื้นที่น้อย จากประสบการณ์ชุมนุมเกษตรของโรงเรียน', '<ol><li>เลือกผักที่โตเร็ว เช่น ผักบุ้ง กะเพรา ต้นหอม</li><li>ใช้ดินผสมปุ๋ยหมัก</li><li>รดน้ำเช้า-เย็น</li><li>วางกระถางในที่มีแดดอย่างน้อย 4 ชั่วโมง</li></ol>', 'เกษตรในโรงเรียน,เศรษฐกิจพอเพียง');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (44, 4, '', 'สรุปแนวทางการประเมินผลการเรียนสำหรับผู้ปกครอง', 'ทำความเข้าใจระดับผลการเรียน การสอบแก้ตัว และการติดตามผลการเรียนของบุตรหลาน', '<p>ผลการเรียนแต่ละรายวิชาแสดงเป็นระดับ 0-4 นักเรียนที่ได้ระดับ 0 มีสิทธิ์สอบแก้ตัวตามกำหนดการของงานวัดผล</p><p>ผู้ปกครองติดตามผลการเรียนได้จากครูที่ปรึกษา หรือสอบถามทาง <a href="{WEBURL}forum">กระดานถาม-ตอบ</a></p>', 'ผู้ปกครอง,วัดผล');
