INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (1, 8, 'ประชุมครูประจำเดือน', '<p>ประชุมครูและบุคลากรประจำเดือน ณ ห้องประชุมโรงเรียน</p>', 'ประชุมครูและบุคลากรประจำเดือน ณ ห้องประชุมโรงเรียน', 'ประชุมครูประจำเดือน', 1, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 0 DAY) + INTERVAL 0 DAY + INTERVAL '16:30' HOUR_MINUTE, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 0 DAY) + INTERVAL '15:30' HOUR_MINUTE, '#0284C7', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (2, 8, 'สอบกลางภาคเรียน', '<p>สอบกลางภาคเรียนทุกระดับชั้น นักเรียนตรวจสอบตารางสอบจากครูที่ปรึกษา</p>', 'สอบกลางภาคเรียนทุกระดับชั้น นักเรียนตรวจสอบตารางสอบจากครูที่ปรึกษา', 'สอบกลางภาคเรียน', 1, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 6 DAY) + INTERVAL 2 DAY + INTERVAL '15:30' HOUR_MINUTE, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 6 DAY) + INTERVAL '08:30' HOUR_MINUTE, '#DC2626', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (3, 8, 'งานวันวิทยาศาสตร์และนิทรรศการวิชาการ', '<p>นิทรรศการผลงานนักเรียน การแสดงทางวิทยาศาสตร์ และการประกวดโครงงาน เปิดให้ชุมชนเข้าชม</p>', 'นิทรรศการผลงานนักเรียน การแสดงทางวิทยาศาสตร์ และการประกวดโครงงาน เปิดให้ชุมชนเข้าชม', 'งานวันวิทยาศาสตร์และนิทรรศการวิชาการ', 1, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 13 DAY) + INTERVAL 0 DAY + INTERVAL '15:00' HOUR_MINUTE, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 13 DAY) + INTERVAL '09:00' HOUR_MINUTE, '#16A34A', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (4, 8, 'ประชุมผู้ปกครองนักเรียน', '<p>ลงทะเบียน 08.30 น. ณ หอประชุม จากนั้นผู้ปกครองพบครูที่ปรึกษา</p>', 'ลงทะเบียน 08.30 น. ณ หอประชุม จากนั้นผู้ปกครองพบครูที่ปรึกษา', 'ประชุมผู้ปกครองนักเรียน', 1, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 20 DAY) + INTERVAL 0 DAY + INTERVAL '12:00' HOUR_MINUTE, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 20 DAY) + INTERVAL '08:30' HOUR_MINUTE, '#E67E22', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (5, 8, 'แข่งขันกีฬาสีภายใน', '<p>การแข่งขันกีฬาสีภายในสองวัน พิธีเปิดเวลา 08.00 น.</p>', 'การแข่งขันกีฬาสีภายในสองวัน พิธีเปิดเวลา 08.00 น.', 'แข่งขันกีฬาสีภายใน', 1, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 26 DAY) + INTERVAL 1 DAY + INTERVAL '16:00' HOUR_MINUTE, (DATE_FORMAT(CURDATE(), '%Y-%m-01') + INTERVAL 26 DAY) + INTERVAL '08:00' HOUR_MINUTE, '#7C3AED', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (6, 8, 'ค่ายลูกเสือ เนตรนารี ม.1', '<p>ค่ายพักแรมลูกเสือ เนตรนารี นักเรียนเตรียมอุปกรณ์ตามรายการที่แจ้ง</p>', 'ค่ายพักแรมลูกเสือ เนตรนารี นักเรียนเตรียมอุปกรณ์ตามรายการที่แจ้ง', 'ค่ายลูกเสือ เนตรนารี ม.1', 1, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 2 DAY) + INTERVAL 2 DAY + INTERVAL '12:00' HOUR_MINUTE, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 2 DAY) + INTERVAL '07:30' HOUR_MINUTE, '#16A34A', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (7, 8, 'ทัศนศึกษาแหล่งเรียนรู้นอกสถานที่', '<p>นักเรียนชั้น ม.2 ทัศนศึกษาพิพิธภัณฑ์และแหล่งเรียนรู้ทางวิทยาศาสตร์</p>', 'นักเรียนชั้น ม.2 ทัศนศึกษาพิพิธภัณฑ์และแหล่งเรียนรู้ทางวิทยาศาสตร์', 'ทัศนศึกษาแหล่งเรียนรู้นอกสถานที่', 1, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 9 DAY) + INTERVAL 0 DAY + INTERVAL '18:00' HOUR_MINUTE, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 9 DAY) + INTERVAL '07:00' HOUR_MINUTE, '#0284C7', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (8, 8, 'สอบปลายภาคเรียน', '<p>สอบปลายภาคเรียนทุกระดับชั้น</p>', 'สอบปลายภาคเรียนทุกระดับชั้น', 'สอบปลายภาคเรียน', 1, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 16 DAY) + INTERVAL 3 DAY + INTERVAL '15:30' HOUR_MINUTE, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 16 DAY) + INTERVAL '08:30' HOUR_MINUTE, '#DC2626', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
INSERT INTO `{prefix}_eventcalendar` (`id`, `module_id`, `topic`, `detail`, `description`, `keywords`, `member_id`, `end_date`, `begin_date`, `color`, `published`, `published_date`, `created_at`, `updated_at`, `last_update`) VALUES (9, 8, 'ประกาศผลการเรียนและรับสมุดรายงาน', '<p>ผู้ปกครองรับสมุดรายงานผลการเรียนจากครูที่ปรึกษา</p>', 'ผู้ปกครองรับสมุดรายงานผลการเรียนจากครูที่ปรึกษา', 'ประกาศผลการเรียนและรับสมุดรายงาน', 1, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 24 DAY) + INTERVAL 0 DAY + INTERVAL '12:00' HOUR_MINUTE, (DATE_FORMAT(CURDATE() + INTERVAL 1 MONTH, '%Y-%m-01') + INTERVAL 24 DAY) + INTERVAL '09:00' HOUR_MINUTE, '#E67E22', 1, CURDATE() - INTERVAL 1 DAY, NOW() - INTERVAL 7 DAY, NOW() - INTERVAL 7 DAY, UNIX_TIMESTAMP(NOW() - INTERVAL 7 DAY));
