INSERT INTO `{prefix}_board_q` (`id`, `module_id`, `category_id`, `sender`, `member_id`, `email`, `ip`, `visited`, `comments`, `comment_id`, `commentator`, `commentator_id`, `comment_date`, `picture`, `can_reply`, `published`, `pin`, `locked`, `topic`, `detail`, `created_at`, `updated_at`) VALUES (7, 10, 3, 'ผู้ปกครอง', 1, '', '', 45, 1, 10, 'กลุ่มสาระวิทยาศาสตร์', 1, NOW() - INTERVAL 6 DAY - INTERVAL 1 HOUR, NULL, 1, 1, 0, 0, 'ขอบคุณคุณครูที่ดูแลนักเรียนในค่ายวิทยาศาสตร์', '<p>ลูกกลับมาเล่าเรื่องค่ายอย่างสนุกสนาน ขอบคุณคุณครูทุกท่านค่ะ</p>', NOW() - INTERVAL 7 DAY - INTERVAL 2 HOUR, NOW() - INTERVAL 6 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (1, 10, 2, '<p>แนบสำเนาทะเบียนบ้าน หลักฐานการศึกษา และรูปถ่ายเป็นไฟล์ได้เลยครับ เอกสารตัวจริงนำมาแสดงในวันมอบตัวครับ</p>', 'งานรับสมัคร', 1, '', '', NULL, NOW() - INTERVAL 3 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (2, 10, 2, '<p>ขอบคุณค่ะ</p>', 'ผู้ปกครอง', 1, '', '', NULL, NOW() - INTERVAL 2 DAY - INTERVAL 2 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (3, 10, 3, '<p>มีบริการ 2 เส้นทางครับ สอบถามเส้นทางและค่าบริการได้ที่ห้องธุรการในวันทำการครับ</p>', 'งานธุรการ', 1, '', '', NULL, NOW() - INTERVAL 8 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (4, 10, 4, '<p>ประกาศแล้วครับ ดูได้ที่ปฏิทินกิจกรรมและรับตารางสอบจากครูที่ปรึกษาครับ</p>', 'งานวัดผล', 1, '', '', NULL, NOW() - INTERVAL 5 DAY - INTERVAL 1 HOUR);
