INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (6, 10, 4, '<p>ขอให้ตั้งใจสอบนะครับ</p>', 'งานวัดผล', 1, '', '', NULL, NOW() - INTERVAL 3 DAY - INTERVAL 3 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (7, 10, 5, '<p>สั่งซื้อได้ที่ร้านสหกรณ์โรงเรียนครับ เปิดทุกวันทำการ 07.30 - 16.00 น.</p>', 'งานกิจการนักเรียน', 1, '', '', NULL, NOW() - INTERVAL 14 DAY - INTERVAL 1 HOUR);
INSERT INTO `{prefix}_board_r` (`id`, `module_id`, `index_id`, `detail`, `sender`, `member_id`, `email`, `ip`, `picture`, `updated_at`) VALUES (8, 10, 6, '<p>เปิดรับสมัครต้นภาคเรียนครับ สนใจมาพบครูที่ห้องปฏิบัติการคอมพิวเตอร์ได้เลยครับ</p>', 'ครูที่ปรึกษาชุมนุม', 1, '', '', NULL, NOW() - INTERVAL 19 DAY - INTERVAL 1 HOUR);
